Full working solution:

function airportLuggageConveyor(bags, trips) {
  let low = Math.max(...bags);
  let high = bags.reduce((sum, weight) => sum + weight, 0);

  function canShip(capacity) {
    let usedTrips = 1;
    let current = 0;

    for (const weight of bags) {
      if (current + weight > capacity) {
        usedTrips++;
        current = weight;
      } else {
        current += weight;
      }
    }

    return usedTrips <= trips;
  }

  while (low < high) {
    const mid = Math.floor((low + high) / 2);

    if (canShip(mid)) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }

  return low;
}

Time complexity: O(n log S), where n is bags.length and S is the sum range.
Space complexity: O(1).

