function nightMarketCouponCombo(prices, target) {
  if (prices.length < 3) return false;

  prices.sort((a, b) => a - b);

  for (let i = 0; i < prices.length - 2; i++) {
    let left = i + 1;
    let right = prices.length - 1;

    while (left < right) {
      const sum = prices[i] + prices[left] + prices[right];

      if (sum === target) return true;

      if (sum < target) {
        left++;
      } else {
        right--;
      }
    }
  }

  return false;
}

Time complexity: O(n^2), where n is prices.length.
Space complexity: O(1) if sorting is done in place, depending on the language implementation.
